  });

  it('切 decision tab → decision 走反查（active 无槽位，反查是该 phase / attempt 下 decision 会话唯一寻址）', async () => {
    sessionsFixture = {
      [`${CHANGE_ID}/implement/decision/2`]: [
        transcriptSession('ses-decision-2', `${CHANGE_ID}/implement/decision/2`),
      ],
    };
    transcriptFixture = { 'ses-decision-2': [textEvent(0, 'assistant', '决策已落库正文')] };
    renderTranscriptDrawer(activeWorld(), { scope: 'node', nodeId: 'active:implement:2' });

    await screen.findByTestId('session-transcript-panel');
    fireEvent.click(
      within(screen.getByTestId('session-transcript-panel')).getAllByTestId(
        'transcript-role-tab',
      )[2],
    );
    await waitFor(() =>
      expect(screen.getByTestId('session-transcript-panel').getAttribute('data-role')).toBe(
        'decision',
      ),
    );
    await waitFor(() =>
      expect(invokeMock).toHaveBeenCalledWith('agent_sessions', {
        root: 'root-a',
        source: 'change',
        sourceRef: `${CHANGE_ID}/implement/decision/2`,
      }),
    );
    await waitFor(() => expect(panelTexts()).toEqual(['决策已落库正文']));
  });

  it('未开跑角色（反查空清单）→ 切该 tab 呈 transcript-empty「（暂无该会话转录）」、零进一步查询', async () => {
    sessionsFixture = {
      [`${CHANGE_ID}/implement/executor/2`]: [
        transcriptSession('ses-exec-2', `${CHANGE_ID}/implement/executor/2`),
      ],
    };
    transcriptFixture = { 'ses-exec-2': [textEvent(0, 'user', '执行正文')] };
    renderTranscriptDrawer(activeWorld(), { scope: 'node', nodeId: 'active:implement:2' });

    await waitFor(() => expect(panelTexts()).toEqual(['执行正文']));
    fireEvent.click(
      within(screen.getByTestId('session-transcript-panel')).getAllByTestId(
        'transcript-role-tab',
      )[1],
    );
    await waitFor(() => expect(screen.getByTestId('transcript-empty') !== null).toBe(true));
    expect(screen.getByTestId('transcript-empty').textContent).toBe('（暂无该会话转录）');
    // 反查恰 executor + evaluator 两路（decision tab 未激活不取数）；转录重放仅命中会话一路
    const sessionRefs = (invokeMock.mock.calls as unknown[][])
      .filter((call) => call[0] === 'agent_sessions')
      .map((call) => (call[1] as { sourceRef?: string } | undefined)?.sourceRef);
    expect(sessionRefs).toEqual([
      `${CHANGE_ID}/implement/executor/2`,
      `${CHANGE_ID}/implement/evaluator/2`,
    ]);
    expect(
      (invokeMock.mock.calls as unknown[][]).filter(
        (call) => call[0] === 'agent_session_transcript',
      ),
    ).toHaveLength(1);
  });

  it('active 节点联动不依赖实时事件流（实时面统一转录库——refreshKey 缺省即重放单源）', async () => {
    sessionsFixture = {
      [`${CHANGE_ID}/implement/executor/2`]: [
        transcriptSession('ses-exec-2', `${CHANGE_ID}/implement/executor/2`),
      ],
    };
    transcriptFixture = { 'ses-exec-2': [textEvent(0, 'user', '仅重放正文')] };
    renderTranscriptDrawer(activeWorld(), { scope: 'node', nodeId: 'active:implement:2' });

    await waitFor(() => expect(panelTexts()).toEqual(['仅重放正文']));
    expect(screen.getByTestId('session-transcript-panel').textContent).not.toContain(
      '实时增量不出现',
    );
  });

  it('sourceRef 定式与 active 节点 id 同参：active:<phase>:<attempt> 与 <id>/<phase>/<role>/<attempt> 同 attempt 组装', async () => {
    sessionsFixture = {
      [`${CHANGE_ID}/implement/executor/2`]: [
        transcriptSession('ses-exec-2', `${CHANGE_ID}/implement/executor/2`),
      ],
    };
    transcriptFixture = { 'ses-exec-2': [textEvent(0, 'user', '同参正文')] };
    renderTranscriptDrawer(activeWorld(), { scope: 'node', nodeId: 'active:implement:2' });

    const panel = await screen.findByTestId('session-transcript-panel');
    await waitFor(() => expect(panelTexts()).toEqual(['同参正文']));
    // 四段定式第二三段与节点 id `active:implement:2` 的 phase / attempt 同参
    const call = (invokeMock.mock.calls as unknown[][]).find(
      (entry) => entry[0] === 'agent_sessions',
    );
    const params = call?.[1] as { sourceRef?: string } | undefined;
    expect(params?.sourceRef).toBe(`${CHANGE_ID}/implement/executor/2`);
    expect(panel.getAttribute('data-role')).toBe('executor');
  });
});

// ---------------------------------------------------------------------------
// 右列二分节退役面（desktop-workflow-db-state）：FileLogTable 载体与 hasFileLog
// 链路删除——右列恒「本站文档 / 评估记录」二分节，文件表节与「文件」标题在
// 任何输入（含历史上曾有 fileLog 的形态）下不出现。
// ---------------------------------------------------------------------------

/** 多 attempt + 多产物夹具：历史上会带 fileLog（文件表节挂载）的形态——
 * fileLog 已不在 ChangeDetail 类型面，夹具携带该字段即编译失败。 */
function fileLogShapedWorld(): World {
  return world({
    detail: {
      pipeline: PIPELINE_PHASES.map((phase) => ({
        phase,
        attempts: phase === 'dev-design' ? [attempt({ attempt: 1 }), attempt({ attempt: 2 })] : [],
      })),
      artifacts: [
        { kind: 'markdown-doc', source: 'design.md', title: '设计' },
        { kind: 'tasks-progress', source: 'tasks.md', title: '任务进度' },
      ],
    },
    materials: {
      columnDocs: {
        'col:dev-design': [envelope('markdown-doc', '设计文档', { markdown: '# 设计' })],
      },
    },
  });
}

describe('DetailDrawer：右列二分节退役面（文件表节删除）', () => {
  it('多 attempt + 多产物夹具（历史上曾有 fileLog 的形态）→ 右列恰二分节，文件表节与「文件」标题不出现', () => {
    const { container } = renderDrawer(fileLogShapedWorld(), {
      scope: 'column',
      phase: 'dev-design',
    });

    // 二分节：右列容器恰两个直接子节（本站文档 / 评估记录），挂载 testid 齐备
    const rightColumn = screen.getByTestId('drawer-docs-section').parentElement;
    expect(rightColumn?.childElementCount).toBe(2);
    expect(screen.getByTestId('drawer-eval-section') !== null).toBe(true);
    // 文件表节退役：historical testid、节标题与降级文案零残留
    expect(screen.queryByTestId('drawer-files-section')).toBeNull();
    const fileHeadings = within(container)
      .queryAllByRole('heading')
      .filter((heading) => (heading.textContent ?? '').includes('文件'));
    expect(fileHeadings).toHaveLength(0);
    expect(container.textContent).not.toContain('文件清单');
    expect(container.textContent).not.toContain('不聚合文件表');
  });

  it('文件表挂载分支退役：任意 selection（列头 / eval 节点）下文件表恒不挂载，右列分节数恒为 2', () => {
    const selections: DrawerSelection[] = [
      { scope: 'column', phase: 'dev-design' },
      { scope: 'node', nodeId: 'eval:dev-design:2' },
    ];
    for (const selection of selections) {
      const { container, unmount } = renderDrawer(fileLogShapedWorld(), selection);
      expect(screen.queryByTestId('drawer-files-section')).toBeNull();
      const rightColumn = screen.getByTestId('drawer-docs-section').parentElement;
      expect(rightColumn?.childElementCount).toBe(2);
      expect(container.textContent).not.toContain('文件清单');
      unmount();
    }
  });
});

