  it('自由文本应答：非空提交触发 answer(trimmed) 且输入清空；空白提交不触发', () => {
    const answer = vi.fn(async () => {});
    renderPanel(runStub({ answer }), {
      activeRun: activeRun({
        status: 'waitingAsk',
        ask: { question: '继续还是停止？', options: [] },
      }),
