    expect(answer).toHaveBeenCalledTimes(1);
  });

  it('options 空数组：无选项按钮、自由应答通道仍可用', () => {
    const answer = vi.fn(async () => {});
    renderPanel(runStub({ answer }), {
      activeRun: activeRun({
        status: 'waitingAsk',
        ask: { question: '是否继续？', options: [] },
