  it('ask 输入初值：挂载即空串（未输入前不携脏值——初值 useState 可辨）', () => {
    renderPanel(runStub(), {
      activeRun: activeRun({
        status: 'waitingAsk',
        ask: { question: '继续还是停止？', options: [] },
      }),
      lastRun: null,
